func (s *MemoryPolicyStore) snapshotNode(
	nodeID shoal.ID,
) (NodeRegistration, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	registration, ok := s.nodes[nodeID]
	if !ok {
		return NodeRegistration{}, false
	}
	cloned, err := cloneNodeRegistration(registration)
	if err != nil {
		return NodeRegistration{}, false
	}
	return cloned, true
}

