func nodesEqual(left, right graph.Node) bool {
	if left.ID != right.ID || left.Kind != right.Kind ||
		len(left.Labels) != len(right.Labels) ||
		len(left.Properties) != len(right.Properties) {
		return false
	}
	for index := range left.Labels {
		if left.Labels[index] != right.Labels[index] {
			return false
		}
	}
	for key, value := range left.Properties {
		if right.Properties[key] != value {
			return false
		}
	}
	return true
}

func putDerivedGraphNode(nodes map[shoal.ID]graph.Node, node graph.Node) error {
	if existing, exists := nodes[node.ID]; exists && !nodesEqual(existing, node) {
		return shoal.NewError(
			shoal.ErrorConflict,
			"derived graph node ID already has different content",
		)
	}
	nodes[node.ID] = node
	return nil
}

func (e *Explorer) assertionsForEdgesLocked(
	edges map[shoal.ID]graph.Edge,
) []ontology.Assertion {
	seen := make(map[shoal.ID]struct{}, len(edges))
	ids := make([]shoal.ID, 0, len(edges))
	for id := range edges {
		if _, ok := e.graphAssertions[id]; ok {
			seen[id] = struct{}{}
			ids = append(ids, id)
			continue
		}
		edge := e.graphEdges[id]
		if edge.Type != graph.EdgeTypeProduced {
			continue
		}
		assertionID, ok := edge.Properties[latentAssertionEdgePropertyAssertionID]
		if !ok {
			continue
		}
		id := shoal.ID(assertionID)
		if _, ok := e.graphAssertions[id]; !ok {
			continue
		}
		if _, duplicate := seen[id]; duplicate {
			continue
		}
		seen[id] = struct{}{}
		ids = append(ids, id)
	}
	sortIDs(ids)
	assertions := make([]ontology.Assertion, 0, len(ids))
	for _, id := range ids {
		assertions = append(assertions, e.graphAssertions[id])
	}
	return assertions
}

