// advanceProposalTransitionTime returns the earliest time that keeps a
// proposal's lifecycle strictly ordered. Callers derive at from the wall
// clock, whose granularity on some platforms is coarser than the interval
// between two consecutive transitions, so at can equal the preceding
// timestamp even though real time moved forward.
func advanceProposalTransitionTime(
	current ontology.GovernedProposal, at time.Time,
) time.Time {
	previous := current.CreatedAt()
	if transitions := current.Transitions(); len(transitions) > 0 {
		previous = transitions[len(transitions)-1].At()
	}
	if at.After(previous) {
		return at
	}
	return previous.Add(time.Nanosecond)
}

// TestOntologyProposalTransitionsSurviveCoarseClockGranularity pins that a
// lifecycle driven faster than the wall clock ticks still advances. Callers
// read the clock once per transition, and on platforms whose granularity is
// coarser than the work between two transitions every read returns the same
// instant.
func TestOntologyProposalTransitionsSurviveCoarseClockGranularity(t *testing.T) {
	corpus, err := Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer corpus.Close()

	base := proposalClockOntologyVersion(t, "v1")
	proposed := proposalClockOntologyVersion(t, "v2")
	frozen := time.Date(2026, 9, 4, 0, 0, 0, 0, time.UTC)

	proposal, err := ontology.NewGovernedProposal(
		base.Schema(), base, proposed, "proposer", "coarse clock", frozen, nil)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	if err := corpus.CreateOntologyProposal(ctx, proposal, base); err != nil {
		t.Fatal(err)
	}

	states := []ontology.ProposalState{
		ontology.ProposalSubmitted,
		ontology.ProposalApproved,
		ontology.ProposalPublished,
	}
	var updated ontology.GovernedProposal
	for _, state := range states {
		updated, err = corpus.TransitionOntologyProposal(
			ctx, proposal.ID(), state, "approver", "advancing lifecycle", frozen)
		if err != nil {
			t.Fatalf("transition to %s with an unchanged clock reading: %v", state, err)
		}
	}

	transitions := updated.Transitions()
	if len(transitions) != len(states) {
		t.Fatalf("transition count = %d, want %d", len(transitions), len(states))
	}
	previous := updated.CreatedAt()
	for i, transition := range transitions {
		if !transition.At().After(previous) {
			t.Fatalf("transition %d at %s does not follow %s",
				i, transition.At(), previous)
		}
		previous = transition.At()
	}
	if err := updated.Validate(); err != nil {
		t.Fatalf("proposal advanced past a coarse clock is invalid: %v", err)
	}
}

func proposalClockOntologyVersion(t *testing.T, version string) ontology.OntologyVersion {
	t.Helper()
	name, err := ontology.NewPropertyDefinition(
		"name", "Name", "Display name", ontology.ValueString, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	person, err := ontology.NewConceptDefinition(
		"person", "Person", "A person", []shoal.ID{name.ID()}, nil)
	if err != nil {
		t.Fatal(err)
	}
	schema, err := ontology.NewOntologySchema(
		"workspace", "Workspace", "Workspace ontology", nil)
	if err != nil {
		t.Fatal(err)
	}
	built, err := ontology.NewOntologyVersion(
		schema, version, time.Date(2026, 9, 4, 0, 0, 0, 0, time.UTC),
		[]ontology.ConceptDefinition{person}, nil,
		[]ontology.PropertyDefinition{name}, nil,
	)
	if err != nil {
		t.Fatal(err)
	}
	return built
}

func (c *Client) derivedAssertionEndpointsAllow(
	ctx context.Context,
	rawNodes map[shoal.ID]graph.Node,
	visibleNodes map[shoal.ID]graph.Node,
	resolved registeredNodes,
	assertion ontology.Assertion,
	decision auth.Decision,
	operation auth.Operation,
	now time.Time,
) (bool, error) {
	target, ok := assertion.Object().ReferenceValue()
	if !ok {
		return false, nil
	}
	allowed, err := edgeEndpointsAllow(
		resolved,
		EdgeRegistration{Edge: graph.Edge{
			ID: assertion.ID(), From: assertion.Subject(), To: target,
			Type: string(assertion.Predicate()), Weight: assertion.Confidence(),
		}},
		decision,
		operation,
		now,
	)
	if err != nil || !allowed {
		return allowed, err
	}
	registrations := map[shoal.ID]NodeRegistration{
		assertion.Subject(): resolved[assertion.Subject()],
		target:              resolved[target],
	}
	canonical, err := c.canonicalRegisteredNodes(ctx, registrations)
	if err != nil {
		return false, err
	}
	for _, nodeID := range []shoal.ID{assertion.Subject(), target} {
		node, ok := rawNodes[nodeID]
		if !ok || !graphNodesEqual(canonical[nodeID], node) {
			return false, inconsistentBase()
		}
		visibleNodes[nodeID] = cloneGraphNode(node)
	}
	return true, nil
}

func derivedAssertionMatchesEdge(assertion ontology.Assertion, edge graph.Edge) bool {
	target, ok := assertion.Object().ReferenceValue()
	if !ok {
		return false
	}
	return edge.ID == assertion.ID() &&
		edge.From == assertion.Subject() &&
		edge.To == target &&
		edge.Type == string(assertion.Predicate()) &&
		scoresEqual(edge.Weight, assertion.Confidence())
}

func derivedAssertionsByEdge(
	assertions []ontology.Assertion,
) (map[shoal.ID]ontology.Assertion, error) {
	byEdge := make(map[shoal.ID]ontology.Assertion, len(assertions))
	for _, assertion := range assertions {
		if err := assertion.Validate(); err != nil {
			return nil, inconsistentBase()
		}
		if assertion.Origin() != ontology.AssertionDerived {
			return nil, inconsistentBase()
		}
		if _, ok := assertion.Object().ReferenceValue(); !ok {
			return nil, inconsistentBase()
		}
		if _, duplicate := byEdge[assertion.ID()]; duplicate {
			return nil, inconsistentBase()
		}
		byEdge[assertion.ID()] = assertion
	}
	return byEdge, nil
}

// Neighborhood filters by current node and edge rules, then recomputes
// reachability so hidden intermediates cannot disclose or bridge.
func (c *Client) Neighborhood(
	ctx context.Context,
	request explorer.NeighborhoodRequest,
) (explorer.Neighborhood, error) {
	normalized, err := request.Normalize()
	if err != nil {
		return explorer.Neighborhood{}, err
	}
	decision, guard, now, err := c.begin(ctx, auth.OperationNeighborhood)
	if err != nil {
		return explorer.Neighborhood{}, err
	}
	for _, nodeID := range normalized.NodeIDs {
		if _, err := c.authorizedNode(
			ctx, nodeID, decision, auth.OperationNeighborhood, now); err != nil {
			return explorer.Neighborhood{}, err
		}
	}
	raw, err := c.base.Neighborhood(ctx, normalized)
	if err != nil {
		return explorer.Neighborhood{}, directBaseError(err)
	}
	result, err := c.filterNeighborhood(
		ctx, raw, normalized, explorer.GraphDirectionBoth, decision, now)
	if err != nil {
		return explorer.Neighborhood{}, err
	}
	if err := guard.Check(ctx); err != nil {
		return explorer.Neighborhood{}, err
	}
	return result, nil
}

