			edges[edge.ID] = edge
		}
	}
	for _, record := range e.folds {
		for _, edge := range record.Edges {
			if _, from := nodes[edge.From]; !from {
				continue
			}
			if _, to := nodes[edge.To]; !to {
				continue
			}
			edges[edge.ID] = edge
		}
	}
	return nodes, edges, nil
}

