	return json.Marshal(struct {
		Snapshot   Snapshot        `json:"snapshot"`
		Path       wirePath        `json:"path"`
		Assertions []wireAssertion `json:"assertions,omitempty"`
	}{r.Snapshot, wirePathValue(r.Path), assertions})
}

