func TestCausalInference_TieBreaksByNeighbor(t *testing.T) {
	cells := sortCausalInput([]kv{
		{mk("S", "V", "_embedding", "", 1), embed(1, 0)},
		{mk("S", "E_z", "a", "", 2), []byte("{}")},
		{mk("S", "E_a", "b", "", 3), []byte("{}")},
		{mk("a", "V", "_embedding", "", 4), embed(1, 0)},
